import{_ as t,o as a,c as r,a2 as i}from"./chunks/framework.CDpkVv68.js";const m=JSON.parse('{"title":"Magic presentation and modular VFX","description":"","frontmatter":{},"headers":[],"relativePath":"game-design/magic/presentation.md","filePath":"game-design/magic/presentation.md"}'),n={name:"game-design/magic/presentation.md"};function s(o,e,d,l,c,p){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="magic-presentation-and-modular-vfx" tabindex="-1">Magic presentation and modular VFX <a class="header-anchor" href="#magic-presentation-and-modular-vfx" aria-label="Permalink to &quot;Magic presentation and modular VFX&quot;">​</a></h1><p><strong>Design status:</strong> Proposed; listed decisions remain Unresolved. Existing Accepted foundations retain their scope. <strong>Implementation:</strong> no Batch 04 gameplay implementation established. <strong>Availability:</strong> not established for this redesign. <strong>Verification:</strong> documentation reconciliation only, not runtime validation. <strong>Reviewed:</strong> 2026-10-09 against Batch 04 and <a href="/Syrolands-Public/game-design/magic.html">earlier magic design</a>.</p><p><a href="/Syrolands-Public/guide/magic/variants-and-glyphs.html">Player guide</a> · <a href="/Syrolands-Public/game-design/magic.html">Magic overview</a> · <a href="/Syrolands-Public/game-design/magic/status-and-open-questions.html">Status and open questions</a></p><h2 id="a-reusable-visual-grammar" tabindex="-1">A reusable visual grammar <a class="header-anchor" href="#a-reusable-visual-grammar" aria-label="Permalink to &quot;A reusable visual grammar&quot;">​</a></h2><p>Variant combinations need a scalable visual language that communicates mechanics. Core Patterns select a visual family such as projectile, beam, burst, field, aura, rune, wave or impact. Modifiers may alter or layer hue/color, scale, trail, particle density, impact, decal, pulse, duration, residual field and sound. These are presentation requirements/candidates, not proof that the current renderer supports those features.</p><table tabindex="0"><thead><tr><th>Example</th><th>Proposed visual reading</th></tr></thead><tbody><tr><td>Fireball</td><td>Base fire projectile</td></tr><tr><td>Fireball + Compression</td><td>Smaller/tighter projectile, denser trail, sharper impact</td></tr><tr><td>Fireball + Persistence</td><td>Base impact plus lingering embers/ground field</td></tr></tbody></table><p>A compressed/penetrating variation should read as such; a persistent field should visibly persist. Avoid hundreds of bespoke assets where reusable composition conveys the same differences. Readability and counterplay constrain visual complexity alongside the bounded modifier model.</p><h2 id="presentation-is-not-authority" tabindex="-1">Presentation is not authority <a class="header-anchor" href="#presentation-is-not-authority" aria-label="Permalink to &quot;Presentation is not authority&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Boundary</th><th>Magic example</th></tr></thead><tbody><tr><td>USER INTENT</td><td>Request a prepared or referenced variant at a target/region</td></tr><tr><td>AUTHORITATIVE SERVER STATE</td><td>Validate knowledge, memory, resources, reference/cast timing, interruption and actual effects</td></tr><tr><td>SYNCHRONIZED STATE</td><td>Only server-approved information suitable for recipients; exact contract unresolved</td></tr><tr><td>CLIENT PRESENTATION</td><td>Book reading, projectile, impact, sound and residual-field cues</td></tr></tbody></table><p>Sprite pixels, particles, animation completion and client collision never resolve gameplay or gate server outcomes. Displayed duration must follow authoritative lifetime under a future explicit contract.</p><h2 id="renderer-and-input-constraints" tabindex="-1">Renderer and input constraints <a class="header-anchor" href="#renderer-and-input-constraints" aria-label="Permalink to &quot;Renderer and input constraints&quot;">​</a></h2><p>Existing UO effects, sprite layering, hues, reusable animations, client extensions, renderer enhancements and future particle systems are candidates. <strong>No pipeline is selected.</strong> Arbitrary particle/shader composition and physical combat-book interaction are not established ClassicUO capabilities by this batch.</p><p>Renderer constraints preserve coherent drawing/picking, depth, equipment layers, transparency and render order. Future technical work must audit actual assets, sender/receiver contracts and version/fallback support, then measure readability, frame times, overdraw, draw calls and memory in representative scenes. Accessibility, remapping and reliance on color alone need UX review; no performance claim or input binding is finalized.</p><h2 id="open-questions" tabindex="-1">Open questions <a class="header-anchor" href="#open-questions" aria-label="Permalink to &quot;Open questions&quot;">​</a></h2><p>Renderer/input limits, asset feasibility, representation of variants, visibility/disclosure, accessibility, event/schema/capability/fallback contracts, budget limits, timing synchronization and prototype scope. This document creates no effect ID or network allocation.</p>',15)])])}const h=t(n,[["render",s]]);export{m as __pageData,h as default};
